-- Stage one: additive migration. No DROP/TRUNCATE and no inventory posting.
SET NAMES utf8mb4;
-- Preserve orphaned legacy reports without allowing new task IDs to reuse their references.
SET @next_task_id=(SELECT GREATEST(COALESCE((SELECT MAX(id) FROM t_production_task),0),COALESCE((SELECT MAX(task_id) FROM t_production_report),0))+1);
SET @task_sequence_sql=CONCAT('ALTER TABLE t_production_task AUTO_INCREMENT=',@next_task_id);
PREPARE task_sequence FROM @task_sequence_sql;
EXECUTE task_sequence;
DEALLOCATE PREPARE task_sequence;
CREATE TABLE IF NOT EXISTS mm_workshop (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_station (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,workshop_id BIGINT NOT NULL,equipment_id BIGINT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_area (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,warehouse_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_location (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,area_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_team (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,leader_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_member (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,team_id BIGINT NOT NULL,user_id BIGINT NOT NULL,UNIQUE KEY(team_id,user_id),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_shift (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_schedule (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,team_id BIGINT NOT NULL,shift_id BIGINT NOT NULL,station_id BIGINT NOT NULL,equipment_id BIGINT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,INDEX(start_at,end_at),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_check_plan (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,equipment_id BIGINT NOT NULL,interval_days INT NOT NULL,standard VARCHAR(500) NOT NULL,owner_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_check_record (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,plan_id BIGINT NOT NULL,checked_at DATETIME NOT NULL,actual_value VARCHAR(500) NOT NULL,result VARCHAR(20) NOT NULL,remark VARCHAR(500),actor_id BIGINT NOT NULL,maintenance_id BIGINT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_qc_item (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,standard VARCHAR(500) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_qc_template (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,product_id BIGINT NOT NULL,kind VARCHAR(30) NOT NULL,version VARCHAR(30) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_qc_line (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,template_id BIGINT NOT NULL,item_id BIGINT NOT NULL,UNIQUE KEY(template_id,item_id),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_route (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,product_id BIGINT NOT NULL,version VARCHAR(30) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_operation (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,route_id BIGINT NOT NULL,sequence_no INT NOT NULL,station_id BIGINT NOT NULL,predecessor_id BIGINT NULL,standard_minutes DECIMAL(10,2) NOT NULL,requires_qc INT NOT NULL DEFAULT 1,UNIQUE KEY(route_id,sequence_no),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_bom (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,product_id BIGINT NOT NULL,root_material_id BIGINT NOT NULL,version VARCHAR(30) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_bom_line (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,bom_id BIGINT NOT NULL,parent_material_id BIGINT NOT NULL,material_id BIGINT NOT NULL,quantity DECIMAL(14,4) NOT NULL,UNIQUE KEY(bom_id,parent_material_id,material_id),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_product_material (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,product_id BIGINT NOT NULL UNIQUE,material_id BIGINT NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_work_order (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,plan_id BIGINT NOT NULL UNIQUE,bom_id BIGINT NOT NULL,route_id BIGINT NOT NULL,quantity INT NOT NULL,bom_snapshot JSON NOT NULL,route_snapshot JSON NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'CREATED',created_by BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_task_context (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,task_id BIGINT NOT NULL UNIQUE,work_order_id BIGINT NOT NULL,operation_id BIGINT NOT NULL,sequence_no INT NOT NULL,predecessor_id BIGINT NULL,requires_qc INT NOT NULL,is_terminal INT NOT NULL,station_id BIGINT NOT NULL,schedule_id BIGINT NULL,UNIQUE KEY(work_order_id,operation_id),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_inspection (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,template_id BIGINT NOT NULL,kind VARCHAR(30) NOT NULL,source_type VARCHAR(30) NOT NULL,source_id BIGINT NOT NULL,quantity INT NOT NULL,qualified_quantity INT NOT NULL,results JSON NOT NULL,status VARCHAR(30) NOT NULL,actor_id BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_legacy_link (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,source_type VARCHAR(40) NOT NULL,source_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,UNIQUE KEY(source_type,source_id),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mm_audit (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT NOT NULL,resource VARCHAR(60) NOT NULL,action VARCHAR(30) NOT NULL,record_id BIGINT NULL,details TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET @prod=(SELECT id FROM t_product WHERE product_code='PRD-MOUSE-A100');
SET @root=(SELECT id FROM t_material WHERE material_code='MAT-FG-A100');
SET @ws=(SELECT id FROM mm_workshop WHERE code='WS-A100');
SET @equipment=(SELECT id FROM t_equipment WHERE equipment_code='EQ-A100-01');
SET @owner=(SELECT id FROM t_user WHERE deleted=0 AND status<>0 ORDER BY id LIMIT 1);
SET @route=(SELECT id FROM mm_route WHERE code='ROUTE-A100-V1');
SET @bom=(SELECT id FROM mm_bom WHERE code='BOM-A100-V1');

CREATE TABLE IF NOT EXISTS mm_guard(id INT PRIMARY KEY) ENGINE=InnoDB;
SELECT a.warehouse_id,l.code,l.name,'1',0 FROM mm_location l JOIN mm_area a ON a.id=l.area_id
WHERE NOT EXISTS(SELECT 1 FROM t_location old WHERE old.warehouse_id=a.warehouse_id AND old.location_code=l.code);
